"""1350 (#11, corvo_blink_aim_cancel_release_arrive, emily_far_reach_aim_cancel_release_arrive): Record-Coverage-v1332.ps1
with three power cases. The 1332 cases always released the aim, and Far Reach toward a floor point 4.7 m ahead (pitch 20)
was too short to film.
- blinkcancel (Corvo) and farreachcancel (Emily): hold LT to aim, cancel natively with X while LT is held (the native
  cancel of the v26 power regression), let go, then aim and release once more. The partner must present the aim, no
  release scene and no source movement after the cancel, a return to locomotion, and then the release of the second cast.
- farreachfar (Emily): from (-34, -153) facing the 10 m lane (+y) at pitch 10, Far Reach to a floor point about 10 m
  ahead; the camera holds behind the source looking down the lane. The partner must present the release and the source
  must travel more than 5 m.
Generated by make_coverage_v1350.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1332.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:100])
    s = s.replace(old, new)

rep("# 1332 (#11, powers completion)", "# 1350 (#11): Blink and Far Reach aim cancellation, and a long Far Reach. Generated by make_coverage_v1350.py.\n# 1332 (#11, powers completion)")
rep("[string]$Take='coverage-v1332a'", "[string]$Take='coverage-v1350a'")
rep("$corvoPowers=@('blink','darkvision','bendtime','windblast','possession','swarm','possesshuman')",
    "$corvoPowers=@('blink','darkvision','bendtime','windblast','possession','swarm','possesshuman','blinkcancel')")
rep("$emilyPowers=@('farreach','domino','doppelganger','mesmerize','shadowwalk','darkvision')",
    "$emilyPowers=@('farreach','domino','doppelganger','mesmerize','shadowwalk','darkvision','farreachcancel','farreachfar')")
rep("possesshuman=12000;swarm=9000;", "possesshuman=12000;blinkcancel=10500;farreachcancel=10500;farreachfar=9500;swarm=9000;")
rep("$powerNames=@{blink='models/powers/blink/blink.inventoryitem';",
    "$powerNames=@{blinkcancel='models/powers/blink/blink.inventoryitem';farreachcancel='models/powers/grapple/grapple.inventoryitem';farreachfar='models/powers/grapple/grapple.inventoryitem';blink='models/powers/blink/blink.inventoryitem';")
rep("     shadowwalk=@(@(2600,'lt',250),@(4400,'move',1600),@(7600,'lt',250))}",
    "     shadowwalk=@(@(2600,'lt',250),@(4400,'move',1600),@(7600,'lt',250));\n"
    "     blinkcancel=@(@(2600,'lt',3000),@(3900,'ltx',200),@(4200,'neutral',100),@(6400,'lt',1200));\n"
    "     farreachcancel=@(@(2600,'lt',3000),@(3900,'ltx',200),@(4200,'neutral',100),@(6400,'lt',1200));farreachfar=@(,@(2600,'lt',1200))}")
rep("""      switch($d[1]){'lt'{& "$lab/Send-D2Input.ps1" -Role $source -LeftTrigger 255 -DurationMs $d[2]|Out-Null};""",
    """      switch($d[1]){'lt'{& "$lab/Send-D2Input.ps1" -Role $source -LeftTrigger 255 -DurationMs $d[2]|Out-Null};'ltx'{& "$lab/Send-D2Input.ps1" -Role $source -LeftTrigger 255 -Button X -DurationMs $d[2]|Out-Null};'neutral'{& "$lab/Send-D2Input.ps1" -Role $source -DurationMs $d[2]|Out-Null};""")
rep("""C $source "coop_grant_named $($powerNames[$case])";& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 20 -Quick|Out-Null;$step=1}""",
    """C $source "coop_grant_named $($powerNames[$case])";& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $(if($case-eq'farreachfar'){10}else{20}) -Quick|Out-Null;$step=1}""")
cases = "'farreach','domino','doppelganger','mesmerize','shadowwalk'"
rep("}elseif($case-in'crouchheavy','mana','blink','darkvision','bendtime','windblast','possession','swarm'," + cases + "){",
    "}elseif($case-in'crouchheavy','mana','blink','darkvision','bendtime','windblast','possession','swarm'," + cases + ",'blinkcancel','farreachcancel','farreachfar'){")
rep("""    C $source 'setviewpos -35 -153 68.1 0 0';Start-Sleep -Milliseconds 400
    $cx=-35.0;$cy=-153.0+2.8;$cz=66.4+1.5;$cyaw=-90.0;if($case-in'doppelganger','mesmerize','domino','farreach'){$cx=-33.0;$cy=-147.4;$cz=68.4}""",
    """    C $source $(if($case-eq'farreachfar'){'setviewpos -34 -153 68.1 90 0'}else{'setviewpos -35 -153 68.1 0 0'});Start-Sleep -Milliseconds 400
    $cx=-35.0;$cy=-153.0+2.8;$cz=66.4+1.5;$cyaw=-90.0;if($case-in'doppelganger','mesmerize','domino','farreach','farreachcancel'){$cx=-33.0;$cy=-147.4;$cz=68.4}
    if($case-eq'farreachfar'){$cx=-34.0;$cy=-155.6;$cz=68.4;$cyaw=90.0}""")
rep("""-Pitch $(if($case-in'crouchheavy','mana'){15}else{4}) -Quick|Out-Null""",
    """-Pitch $(if($case-in'crouchheavy','mana'){15}elseif($case-eq'farreachfar'){6}else{4}) -Quick|Out-Null""")
rep("if($case-notin'kick','crouchheavy','note','mana','stairs','blink','darkvision','bendtime','windblast','possession','swarm'," + cases + "){",
    "if($case-notin'kick','crouchheavy','note','mana','stairs','blink','darkvision','bendtime','windblast','possession','swarm'," + cases + ",'blinkcancel','farreachcancel','farreachfar'){")
rep("""    $row.checks.Add("$case presented ($($on.Count) samples, variants $($row.powerVariants-join ',')) and recovered")}""",
    """    $row.checks.Add("$case presented ($($on.Count) samples, variants $($row.powerVariants-join ',')) and recovered")
    if($case-in'blinkcancel','farreachcancel'){$aimSet=if($case-eq'blinkcancel'){@(1,2)}else{@(4,5)};$out1=if($case-eq'blinkcancel'){3}else{6}
     $aim=@($samples|Where-Object {$_.ms-ge2600-and$_.ms-lt3900-and[double]$_.powerWeight-gt.5-and[int]$_.powerVariant-in$aimSet}).Count
     $win=@($samples|Where-Object {$_.ms-ge4000-and$_.ms-lt6300})
     $rel=@($win|Where-Object {[double]$_.powerWeight-gt.5-and[int]$_.powerVariant-eq$out1}).Count;$idle=@($win|Where-Object {$_.ms-ge4500-and[double]$_.powerWeight-lt.05}).Count
     $p0=@($samples|Where-Object {$_.ms-ge3700-and$_.position}|Select-Object -First 1);$p1=@($win|Where-Object {$_.position}|Select-Object -Last 1)
     $moved=if($p0.Count-and$p1.Count){[Math]::Sqrt(([Math]::Pow([double]$p1[0].position[0]-[double]$p0[0].position[0],2))+([Math]::Pow([double]$p1[0].position[1]-[double]$p0[0].position[1],2))+([Math]::Pow([double]$p1[0].position[2]-[double]$p0[0].position[2],2)))}else{-1}
     $after=@($samples|Where-Object {$_.ms-ge6400-and[double]$_.powerWeight-gt.5-and[int]$_.powerVariant-eq$out1}).Count
     $row.cancel=[ordered]@{aimSamples=$aim;releaseAfterCancel=$rel;idleAfterCancel=$idle;sourceMovedAfterCancel=[Math]::Round($moved,3);releaseSecondCast=$after}
     if($aim-lt2){throw "$case aim presented in $aim samples before the cancel"};if($rel){throw "$case presented the release ($rel samples) after the cancel"}
     if($moved-lt0-or$moved-gt.3){throw "$case source moved $([Math]::Round($moved,2)) m after the cancel"};if(!$idle){throw "$case did not return to locomotion after the cancel"}
     if(!$after){throw "$case second cast release not presented"}
     $row.checks.Add("Aim presented ($aim samples), cancelled with X: no release, source moved $([Math]::Round($moved,2)) m, locomotion returned ($idle samples); second cast released ($after samples)")}
    if($case-eq'farreachfar'){$ps=@($samples|Where-Object {$_.position});$d=if($ps.Count-ge2){[Math]::Sqrt(([Math]::Pow([double]$ps[-1].position[0]-[double]$ps[0].position[0],2))+([Math]::Pow([double]$ps[-1].position[1]-[double]$ps[0].position[1],2)))}else{0}
     $rel=@($samples|Where-Object {[double]$_.powerWeight-gt.5-and[int]$_.powerVariant-eq6}).Count;$row.farReach=[ordered]@{travel=[Math]::Round($d,2);releaseSamples=$rel}
     if(!$rel){throw 'Far Reach release not presented'};if($d-lt5){throw "Far Reach travelled only $([Math]::Round($d,2)) m"}
     $row.checks.Add("Far Reach released ($rel samples) and travelled $([Math]::Round($d,2)) m down the lane")}}""")
rep("scope='Powers coverage (1332, #11):", "scope='Power cancellation and long Far Reach (1350, #11), on the powers coverage (1332):")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1350.ps1').write_bytes(out.encode('utf-8'))
print('ok')
